import type { SubmitEvent } from "react";

type ReviewDraft = { rating: string; title: string; body: string };
type ReviewFormProps = { onSubmit: (draft: ReviewDraft) => void };

export function ReviewForm({ onSubmit }: ReviewFormProps) {
  function handleSubmit(event: SubmitEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const formData = new FormData(form);

    onSubmit({
      rating: String(formData.get("rating")),
      title: String(formData.get("title")),
      body: String(formData.get("body")),
    });
    form.reset();
  }

  return (
    <form onSubmit={handleSubmit}>
      <label htmlFor="review-rating">Rating</label>
      <select id="review-rating" name="rating" defaultValue="5">
        {[5, 4, 3, 2, 1].map((n) => (
          <option key={n} value={n}>{n} of 5</option>
        ))}
      </select>

      <label htmlFor="review-title">Title</label>
      <input id="review-title" name="title" />

      <label htmlFor="review-body">Review</label>
      <textarea id="review-body" name="body" rows={5} />

      <button type="submit">Post review</button>
    </form>
  );
}

import { useState } from "react";

const MAX = 2000;

export function ReviewBodyField() {
  const [body, setBody] = useState("");
  const left = MAX - body.length;

  return (
    <>
      <label htmlFor="review-body">Review</label>
      <textarea
        id="review-body"
        name="body"
        rows={5}
        maxLength={MAX}
        value={body}
        onChange={(event) => setBody(event.target.value)}
        aria-describedby="review-body-count"
      />
      <p id="review-body-count">
        {left < 200 ? `${left} characters left` : `Up to ${MAX} characters`}
      </p>
    </>
  );
}

import { useActionState } from "react";
import { useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "react-router";
import { SubmitButton } from "@/components/ui/SubmitButton";
import { ApiError, retryAfterSeconds } from "@/lib/api";
import { login } from "./api";
import { meQuery } from "./queries";

type LoginState = { error: string | null; email: string };

export function LoginForm() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  async function logIn(_previous: LoginState, formData: FormData): Promise<LoginState> {
    const email = String(formData.get("email"));
    const password = String(formData.get("password"));

    try {
      const user = await login({ email, password });
      queryClient.setQueryData(meQuery.queryKey, user);
      await navigate("/account");
      return { error: null, email: "" };
    } catch (error) {
      if (error instanceof ApiError && error.status === 401) {
        return { error: "That email and password don't match.", email };
      }
      if (error instanceof ApiError && error.status === 429) {
        const seconds = retryAfterSeconds(error) ?? 60;
        return { error: `Too many tries. Wait ${seconds} seconds, then try again.`, email };
      }
      return { error: "Something went wrong. Try again in a moment.", email };
    }
  }

  const [state, formAction] = useActionState(logIn, { error: null, email: "" });

  return (
    <form action={formAction}>
      <label htmlFor="email">Email</label>
      <input id="email" name="email" type="email" autoComplete="email" required defaultValue={state.email} />

      <label htmlFor="password">Password</label>
      <input id="password" name="password" type="password" autoComplete="current-password" required />

      {state.error && <p role="alert">{state.error}</p>}
      <SubmitButton pendingLabel="Logging in…">Log in</SubmitButton>
    </form>
  );
}

