import { useFormStatus } from "react-dom";

type LoginState = { error: string | null; email: string };

async function logIn(_previous: LoginState, formData: FormData): Promise<LoginState> {
  const email = String(formData.get("email"));
  const response = await fetch("/v1/auth/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password: formData.get("password") }),
  });
  console.log(`action finished: ${response.status}`);
  if (!response.ok) return { error: "That email and password don't match.", email };
  return { error: null, email: "" };
