import { useActionState, useEffect, useRef } from "react";
import { z } from "zod";
import { queryClient } from "@/app/queryClient";
import { SubmitButton } from "@/components/ui/SubmitButton";
import { ApiError } from "@/lib/api";
import { createReview } from "./api";
import { ReviewInput } from "./schemas";

type Fields = Record<keyof ReviewInput, string>;
type ReviewFormState = { message: string | null; errors: Partial<Fields>; values: Partial<Fields> };

const empty: ReviewFormState = { message: null, errors: {}, values: {} };
const messages: Record<number, string> = { 401: "Log in to post a review.", 409: "You've already reviewed this product." };

type ReviewFormProps = { slug: string };

export function ReviewForm({ slug }: ReviewFormProps) {
  const formRef = useRef<HTMLFormElement>(null);

  async function post(_previous: ReviewFormState, formData: FormData): Promise<ReviewFormState> {
    const values = Object.fromEntries(formData) as Fields;
    const parsed = ReviewInput.safeParse(values);
    if (!parsed.success) {
      const { fieldErrors } = z.flattenError(parsed.error);
      const errors = { rating: fieldErrors.rating?.[0], title: fieldErrors.title?.[0], body: fieldErrors.body?.[0] };
      return { message: null, errors, values };
    }

    try {
      await createReview(slug, parsed.data);
      await queryClient.invalidateQueries({ queryKey: ["products", "detail", slug] });
      return empty;
    } catch (error) {
      if (!(error instanceof ApiError)) return { message: "Your review didn't post. Try again.", errors: {}, values };
      if (error.status === 422) return { message: null, errors: error.problem.errors ?? {}, values };
      return { message: messages[error.status] ?? error.message, errors: {}, values };
    }
  }

  const [state, formAction] = useActionState(post, empty);

  useEffect(() => {
    formRef.current?.querySelector<HTMLElement>("[aria-invalid='true']")?.focus();
  }, [state]);

  const field = (name: keyof Fields) => ({
    id: `review-${name}`,
    name,
    defaultValue: state.values[name],
    "aria-invalid": state.errors[name] ? true : undefined,
    "aria-describedby": state.errors[name] ? `review-${name}-error` : undefined,
  });
  const error = (name: keyof Fields) =>
    state.errors[name] && <p id={`review-${name}-error`} className="field-error">{state.errors[name]}</p>;

  return (
    <form ref={formRef} action={formAction} noValidate>
      <label htmlFor="review-rating">Rating</label>
      <select {...field("rating")} required>
        <option value="">Choose…</option>
        {[5, 4, 3, 2, 1].map((n) => <option key={n} value={n}>{n} of 5</option>)}
      </select>
      {error("rating")}

      <label htmlFor="review-title">Title</label>
      <input {...field("title")} required maxLength={80} />
      {error("title")}

      <label htmlFor="review-body">Review</label>
      <textarea {...field("body")} required maxLength={2000} rows={5} />
      {error("body")}

      {state.message && <p role="alert">{state.message}</p>}
      <SubmitButton pendingLabel="Posting…">Post review</SubmitButton>
    </form>
  );
}

import { useOptimistic } from "react";
import { useQuery, useSuspenseInfiniteQuery } from "@tanstack/react-query";
import { meQuery } from "@/features/auth";
import { reviewsQuery } from "./queries";
import { ReviewForm } from "./ReviewForm";
import type { Review, ReviewInput } from "./schemas";

type ShownReview = Review & { pending?: boolean };
type ReviewsSectionProps = { slug: string };

export function ReviewsSection({ slug }: ReviewsSectionProps) {
  const { data } = useSuspenseInfiniteQuery(reviewsQuery(slug));
  const { data: me } = useQuery(meQuery);
  const reviews: ShownReview[] = data.pages.flatMap((page) => page.items);

  const [shown, addDraft] = useOptimistic(reviews, (current, draft: ShownReview) =>
    current.some((review) => review.author.id === draft.author.id) ? current : [draft, ...current],
  );

  function showDraft(input: ReviewInput) {
    if (!me) return;
    addDraft({
      ...input,
      id: "draft",
      productSlug: slug,
      author: { id: me.id, name: me.name },
      createdAt: new Date().toISOString(),
      pending: true,
    });
  }

  return (
    <section aria-labelledby="reviews-heading">
      <h2 id="reviews-heading">Reviews</h2>
      {me && <ReviewForm slug={slug} onPosting={showDraft} />}
      <ul>
        {shown.map((review) => (
          <li key={review.id} aria-busy={review.pending}>
            <h3>{review.title}</h3>
            <p>
              {review.rating} of 5, by {review.author.name}
              {review.pending && " (posting…)"}
            </p>
            <p>{review.body}</p>
          </li>
        ))}
      </ul>
    </section>
  );
}

steps.body:
A checkout form has seven fields with rules for each, server errors to put back on the right field, and one job that must never happen twice: placing the order. At that size, hand-written wiring gets long, and a mistake costs real money. This part covers the library teams use for big forms, how files travel, and how to make an order safe to send twice.

## React Hook Form

**React Hook Form** is a library that keeps fields uncontrolled, as part 1 recommended, tracks errors and which fields were touched, and re-renders only what has to change. You don't write `value`, `onChange`, or error state for any field.

- `register("shippingAddress.city")` returns the `name`, `ref`, `onChange`, and `onBlur` that hook a field up. You spread them onto the input. The dotted name means the value lands at `shippingAddress.city` in the data, which matches the API's body.
- `resolver: zodResolver(OrderInput)` checks the data with a zod schema, so the same schema style as the review form applies. The resolver comes from a small companion package.
- `handleSubmit(placeOrder)` checks everything first, shows the errors if there are any, and only calls `placeOrder` with clean, typed data when there aren't.
- `formState.errors` has the same shape as the data, so `errors.shippingAddress?.city?.message` is the city's message. `formState.isSubmitting` is true while `placeOrder`'s promise runs.
- `setError(field, { message })` puts a server's message on a field, and `setError("root", ...)` on the whole form.

React Hook Form uses `onSubmit` rather than a form action, and tracks its own pending state. For the login and review forms, React's actions are enough. Reach for the library when a form has many fields, nested data, or fields that come and go.

## Rows that repeat

Some forms have a list in them: a quick-order form where a customer types several product codes and quantities, with a button to add another row. `useFieldArray` manages that list:

```tsx sketch
const { fields, append, remove } = useFieldArray({ control, name: "lines" });
...
{fields.map((field, index) => (
  <fieldset key={field.id}>
    <input aria-label="Product code" {...register(`lines.${index}.slug`)} />
    <input aria-label="Quantity" type="number" {...register(`lines.${index}.quantity`)} />
    <button type="button" onClick={() => remove(index)}>Remove</button>
  </fieldset>
))}
```

Each row gets a stable `field.id` to use as its key, so removing a row in the middle keeps every other row's typing in the right place, as the Components, JSX, and Props lesson explained.

## Sending files

A file input puts a `File` into `FormData`, and `fetch` sends a `FormData` body as **multipart/form-data**, a format that packs several fields, files included, into one request, each part with its own headers. Don't set `Content-Type` yourself for it: the browser adds a boundary string, the marker that separates the parts, and a hand-written header would leave it out. `fetch` gives no progress events for an upload, so a progress bar needs `XMLHttpRequest`, the way browsers made requests before `fetch`, whose `upload` object reports progress:

```ts
export function uploadWithProgress(url: string, formData: FormData, onProgress: (percent: number) => void) {
  return new Promise<number>((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("POST", url);
    xhr.upload.onprogress = (event) => {
      if (event.lengthComputable) onProgress(Math.round((event.loaded / event.total) * 100));
    };
    xhr.onload = () => resolve(xhr.status);
    xhr.onerror = () => reject(new TypeError("The upload failed."));
    xhr.send(formData);
  });
}
```

Trailhead takes no files, so this is the shape for an API that does, like one that adds photos to reviews.

## Orders that must not happen twice

Disabling the button stops a double click. It doesn't stop a request that reached the server and then timed out on the way back: the order exists, your page says it failed, and the person presses again. Nor does it stop a phone that switches networks halfway, or a second tab.

An operation is **idempotent** when doing it twice has the same effect as doing it once. Setting a cart quantity to 2 is idempotent. Placing an order isn't, unless the API helps. The `Idempotency-Key` header is that help: your app makes a unique id for one checkout attempt and sends it with every try. The server remembers the keys it has handled, so a second request with the same key can't make a second order.

Trailhead requires the header on `POST /v1/orders`. It answers 400 without it, 201 with a `Location` header for a new order, and 409 Conflict for a key it has already seen, the same status it gives an empty cart, so the form shows the problem's own `detail`, which says which one it was. The key is a **UUID**, a random 128-bit id written as hex digits and dashes, which `crypto.randomUUID()` makes. The checkout form makes one when it first renders and keeps it in state, so every retry of this checkout sends the same key. After a success the page moves on, and the next checkout renders a fresh form with a fresh key.

Forms are also where attackers start. The next lesson, Web Vulnerabilities and Secrets, covers the attacks every web app has to defend against, and where secret keys must never go.

