import { useState } from "react";
import { useForm, type Path } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useNavigate } from "react-router";
import { queryClient } from "@/app/queryClient";
import { cartQuery } from "@/features/cart";
import { ApiError } from "@/lib/api";
import { createOrder } from "./api";
import { OrderInput } from "./schemas";

const fields = [
  ["name", "Full name", "shipping name"],
  ["line1", "Street address", "shipping address-line1"],
  ["line2", "Apartment or suite (optional)", "shipping address-line2"],
  ["city", "City", "shipping address-level2"],
  ["region", "State or region", "shipping address-level1"],
  ["postalCode", "Postal code", "shipping postal-code"],
  ["country", "Country code, like US", "shipping country"],
] as const;

export function CheckoutForm() {
  const navigate = useNavigate();
  const [idempotencyKey] = useState(() => crypto.randomUUID());
  const { register, handleSubmit, setError, formState } = useForm({
    resolver: zodResolver(OrderInput),
    defaultValues: { shippingAddress: { country: "US" } },
  });
  const { errors, isSubmitting } = formState;

  async function placeOrder(input: OrderInput) {
    try {
      const order = await createOrder(input, idempotencyKey);
      await queryClient.invalidateQueries({ queryKey: cartQuery.queryKey });
      await navigate(`/orders/${order.id}`);
    } catch (error) {
      if (error instanceof ApiError && error.status === 422) {
        for (const [field, message] of Object.entries(error.problem.errors ?? {})) {
          setError(field as Path<OrderInput>, { message });
        }
        return;
      }
      if (error instanceof ApiError && error.status === 409) {
        setError("root", { message: error.problem.detail ?? "This order can't be placed." });
        return;
      }
      setError("root", { message: "Your order didn't go through. Try again in a moment." });
    }
  }

  return (
    <form onSubmit={handleSubmit(placeOrder)} noValidate>
      {fields.map(([name, label, autoComplete]) => {
        const error = errors.shippingAddress?.[name];
        return (
          <div key={name}>
            <label htmlFor={`ship-${name}`}>{label}</label>
            <input
              id={`ship-${name}`}
              autoComplete={autoComplete}
              aria-invalid={error ? true : undefined}
              aria-describedby={error ? `ship-${name}-error` : undefined}
              {...register(`shippingAddress.${name}`)}
            />
            {error && <p id={`ship-${name}-error`} className="field-error">{error.message}</p>}
          </div>
        );
      })}

      {errors.root && <p role="alert">{errors.root.message}</p>}
      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? "Placing your order…" : "Place order"}
      </button>
    </form>
  );
}

import { apiFetch } from "@/lib/api";
import { Order, type OrderInput } from "./schemas";

export function createOrder(input: OrderInput, idempotencyKey: string) {
  return apiFetch("/orders", {
    method: "POST",
    body: input,
    headers: { "Idempotency-Key": idempotencyKey },
    schema: Order,
  });
}
